#!/usr/bin/env bash
#
# Full clean of all (or selected) FabGL2 examples.
#
# For every example project (a folder under examples/ containing sdkconfig.defaults) it removes the files
# generated by ESP-IDF:
#
#   build/  sdkconfig  sdkconfig.old  managed_components/  dependencies.lock
#
# Removing sdkconfig is what makes ESP-IDF apply sdkconfig.defaults again at the next build.
# It also removes the build directories created by tools/build_examples.sh (build_examples/) and by
# the ESP bridge (.bridge/build_*). ESP-IDF does not need to be installed or activated.
#
# Usage:
#
#   tools/clean_examples.sh                    # clean all examples
#   tools/clean_examples.sh VGA/PCEmulator     # clean only examples whose path contains "VGA/PCEmulator"
#   tools/clean_examples.sh -k                 # keep sdkconfig files (remove build outputs only)
#   tools/clean_examples.sh -n                 # dry run: show what would be removed
#
# Options can be combined, e.g. "tools/clean_examples.sh -n -k VGA/".

set -u

ROOT="$(cd "$(dirname "$0")/.." && pwd)"

DRYRUN=0
KEEPCONFIG=0
FILTER=""

for arg in "$@"; do
  case "${arg}" in
    -n) DRYRUN=1 ;;
    -k) KEEPCONFIG=1 ;;
    -h|--help)
      sed -n '2,22p' "$0" | sed 's/^# \{0,1\}//'
      exit 0 ;;
    -*)
      echo "Unknown option: ${arg}" >&2
      exit 1 ;;
    *)  FILTER="${arg}" ;;
  esac
done

removed=0

# removes a file or directory (if it exists)
remove() {
  if [ -e "$1" ] || [ -L "$1" ]; then
    echo "  rm ${1#${ROOT}/}"
    if [ ${DRYRUN} -eq 0 ]; then
      rm -rf "$1"
    fi
    removed=$((removed + 1))
  fi
}

# examples folders
while IFS= read -r defaults; do
  dir="$(dirname "${defaults}")"
  rel="${dir#${ROOT}/examples/}"
  if [ -n "${FILTER}" ] && [[ "${rel}" != *"${FILTER}"* ]]; then
    continue
  fi
  echo "=== ${rel}"
  remove "${dir}/build"
  remove "${dir}/managed_components"
  remove "${dir}/dependencies.lock"
  if [ ${KEEPCONFIG} -eq 0 ]; then
    remove "${dir}/sdkconfig"
    remove "${dir}/sdkconfig.old"
  fi
  # build directories of tools/build_examples.sh and of the ESP bridge
  name="${rel//\//_}"
  remove "${ROOT}/build_examples/${name}"
  remove "${ROOT}/build_examples/${name}.log"
  remove "${ROOT}/.bridge/build_${name}"
done < <(find "${ROOT}/examples" -name sdkconfig.defaults -not -path "*/build/*" | sort)

# remove build_examples/ when it is empty
if [ -z "${FILTER}" ] && [ -d "${ROOT}/build_examples" ] && [ -z "$(ls -A "${ROOT}/build_examples")" ]; then
  remove "${ROOT}/build_examples"
fi

echo
if [ ${DRYRUN} -eq 1 ]; then
  echo "Dry run: ${removed} items would be removed."
else
  echo "Removed ${removed} items."
fi
